export const defaults = Object.freeze({growth:12,margin:24,entry:12,exit:11,leverage:4,interest:8,synergy:8,retention:94,pricing:3,crossSell:5,integration:12});
export const bounds={growth:[-10,30],margin:[10,40],entry:[6,18],exit:[6,18],leverage:[0,6],interest:[3,15],synergy:[0,25],retention:[75,100],pricing:[0,10],crossSell:[0,20],integration:[0,30]};
export function validate(a){for(const [k,[lo,hi]] of Object.entries(bounds))if(!Number.isFinite(a[k])||a[k]<lo||a[k]>hi)throw Error(`Invalid assumption: ${k}`);return a;}
// All amounts USD millions. Fictional target, five annual periods, exit-only sponsor proceeds.
export function model(input){const a=validate({...defaults,...input}), revenue0=100,ebitda0=24,ev=ebitda0*a.entry,fees=ev*.02,debt0=ebitda0*a.leverage,equity=ev+fees-debt0;let revenue=revenue0,debt=debt0,cash=0;const years=[];
for(let year=1;year<=5;year++){const ramp=Math.min(year/3,1), priorRevenue=revenue;revenue=priorRevenue*(1+a.growth/100)*(a.retention/100)*(1+a.pricing/100)+revenue0*a.crossSell/100*ramp;const synergy=a.synergy*ramp,ebitda=revenue*a.margin/100+synergy,interest=debt*a.interest/100,da=revenue*.03,tax=Math.max(0,ebitda-da-interest)*.25,capex=revenue*.04,nwc=(revenue-priorRevenue)*.10,integration=year<=2?a.integration/2:0,fcf=ebitda-interest-tax-capex-nwc-integration,paydown=Math.min(debt,Math.max(0,fcf));debt-=paydown;cash+=fcf-paydown;years.push({year,revenue,synergy,ebitda,interest,tax,capex,nwc,integration,fcf,paydown,debt,cash});}
const last=years.at(-1),exitEV=last.ebitda*a.exit,proceeds=Math.max(0,exitEV-debt+cash),moic=proceeds/equity,irr=moic**.2-1;return {a,ev,fees,debt0,equity,years,exitEV,proceeds,moic,irr,liquidityShortfall:years.some(y=>y.cash<0)};}
export function sensitivity(a){return [-2,-1,0,1,2].map(e=>[-2,-1,0,1,2].map(g=>model({...a,exit:Math.max(6,Math.min(18,a.exit+e)),growth:Math.max(-10,Math.min(30,a.growth+g*2))}).irr));}
export function random(seed=42){let s=seed>>>0;return ()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296;};}
export function simulate(a,n=1000,seed=42){const rng=random(seed),tri=()=>rng()+rng()+rng()-1.5,values=[];for(let i=0;i<n;i++)values.push(model({...a,growth:Math.max(-10,Math.min(30,a.growth+tri()*6)),exit:Math.max(6,Math.min(18,a.exit+tri()*2)),retention:Math.max(75,Math.min(100,a.retention+tri()*4))}).irr);values.sort((a,b)=>a-b);return {values,p10:values[Math.floor(n*.1)],p50:values[Math.floor(n*.5)],p90:values[Math.floor(n*.9)],loss:values.filter(x=>x<0).length/n,hurdle:values.filter(x=>x>=.2).length/n};}
